assert set(annotations) == {r['id'] for r in inventory}
records = []
lines = ['# Inventario académico comentado', '', 'Fuente: Materias.rar. Revisión: 17 de octubre de 2026.', '',
         'Los identificadores F01–F36 corresponden a `inventario.json`. Se conserva el nombre original, incluso cuando no coincide con su contenido. Las propuestas son análisis para una adaptación futura; no son clases implementadas.', '',
         'Administración: carpeta `administraccion` vacía, sin recurso al que asignar identificador.', '']
for r in inventory:
    course, unit, role, content, proposal = annotations[r['id']]
    record = {'id':r['id'], 'course':course, 'placement':unit, 'role':role, 'path':r['path'], 'summary':content, 'proposed_adaptation':proposal, 'sha256':r['sha256']}
    records.append(record)
    link = quote('fuentes/' + r['path'], safe='/')
    lines += [f'## {r["id"]} — {Path(r["path"]).name}', '',
              f'**Ramo / ubicación:** {course} · {unit}. **Tipo:** {role}.', '',
              f'[Abrir fuente original]({link}) · [Texto extraído]({r["text_file"]})', '', content, '',
              '**Adaptación propuesta:** ' + proposal, '']
(root/'INVENTARIO_COMENTADO.md').write_text('\n'.join(lines),encoding='utf-8')
(root/'MAPA_ACADEMICO.json').write_text(json.dumps(records,ensure_ascii=False,indent=2),encoding='utf-8')
print('36 recursos anotados y enlazados. Informe, inventario y mapa preparados.')
